var IMG=["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"];
document.getElementById('hero').src=IMG[0];
document.getElementById('face').src=IMG[3];
var hp='<svg viewBox="0 0 24 22"><path d="M12 21C2 14 3 5 8 5c2 0 4 2 4 2s2-2 4-2c5 0 6 9-4 16z" fill="FILL" stroke="#1A1417" stroke-width="1.5"/></svg>';
document.getElementById('hearts').innerHTML=[1,1,1,1,0].map(function(o){return hp.replace('FILL',o?'#E8999C':'#FFFBFA');}).join('');
var G=[["냥 인사","손을 번쩍 들어 인사하는 날이에요."],["소매 속에 쏙","소매 속에 손을 숨기고 쉬는 날이에요."],["수줍게 숨기","앞발로 얼굴을 살짝 가려 봤어요."],["앞발 쭉","앞발을 쭉 내밀고 안녕 하는 중이에요."]];
var grid=document.getElementById('grid'),dlg=document.getElementById('dlg');
G.forEach(function(g,i){var b=document.createElement('button');b.className='shot';b.innerHTML='<img src="'+IMG[i]+'" alt="'+g[0]+'"><span>'+g[0]+'</span>';
b.onclick=function(){document.getElementById('dimg').src=IMG[i];document.getElementById('dimg').alt=g[0];document.getElementById('dname').textContent=g[0];document.getElementById('dcap').textContent=g[1];dlg.showModal();};grid.appendChild(b);});
document.getElementById('dclose').onclick=function(){dlg.close();};
dlg.addEventListener('click',function(e){if(e.target===dlg)dlg.close();});
var on=false;
/* 곡마다 마지막 칸에 유튜브 링크를 넣으면 재생 버튼을 눌렀을 때 그 영상이 재생돼요. */
var T=[["고양이 걸음","DANI’S PICK",240,"https://youtu.be/uVFS_1CFS0Y?si=-zMFmrFjAeXUO66z"],["하트 앞치마","DANI’S PICK",221,"https://youtu.be/qLYeeuG2b1U?si=mc9Ub1IjodDINVS8"],["새벽 두 시의 메이드","DANI’S PICK",175,"https://youtu.be/UJ6fZnNyGFE?si=zFaJu922o2UQtpGT"],["흑백 사진관","DANI’S PICK",203,"https://youtu.be/aP-kOl1QZck?si=9SBqp0XR7DzI7XQ2"],["분홍빛 바닥","DANI’S PICK",238,"https://youtu.be/qwlsFE_vYHk?si=PW6cw4ed6k_-J_3i"]];
var cur=0,pos=0,timer=null,player=document.getElementById('player'),list=document.getElementById('list'),playBtn=document.getElementById('play');
function mmss(s){return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2);}
function render(){var t=T[cur];document.getElementById('tt').textContent=t[0];document.getElementById('ta').textContent=t[1];document.getElementById('im').textContent=ytId(t[3])?'재생을 누르면 영상이 나와요':'이 곡은 아직 영상 링크가 없어요';
document.getElementById('bar').style.width=(pos/t[2]*100)+'%';
Array.prototype.forEach.call(list.querySelectorAll('button'),function(b,i){if(i===cur)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');});}
T.forEach(function(t,i){var li=document.createElement('li'),b=document.createElement('button');b.innerHTML='<span>'+t[0]+'</span><span>'+mmss(t[2])+'</span>';b.onclick=function(){go(i,true);};li.appendChild(b);list.appendChild(li);});
function go(i,a){cur=(i+T.length)%T.length;pos=0;render();if(a)start();}
function ytId(u){var m=(u||'').match(/(?:youtu\.be\/|v=|embed\/|shorts\/)([\w-]{11})/);return m?m[1]:'';}
function start(){stop();on=true;player.classList.add('playing');playBtn.textContent='❚❚';playBtn.setAttribute('aria-label','일시정지');var id=ytId(T[cur][3]),y=document.getElementById('yt');
if(id){y.hidden=false;document.getElementById('idle').hidden=true;y.innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/'+id+'?autoplay=0&rel=0&playsinline=1" title="'+T[cur][0]+'" allow="autoplay; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>';timer=setInterval(function(){pos++;if(pos>=T[cur][2]){clearInterval(timer);return;}render();},1000);return;}
timer=setInterval(function(){pos++;if(pos>=T[cur][2]){go(cur+1,true);return;}render();},1000);}
function stop(){clearInterval(timer);timer=null;on=false;var y=document.getElementById('yt');y.hidden=true;y.innerHTML='';document.getElementById('idle').hidden=false;player.classList.remove('playing');playBtn.textContent='▶';playBtn.setAttribute('aria-label','재생');}
playBtn.onclick=function(){on?stop():start();};
document.getElementById('next').onclick=function(){go(cur+1,on);};
document.getElementById('prev').onclick=function(){go(cur-1,on);};
render();
